//! Brain Trauma Foundation publisher recommendation indexes, distinct from full PDFs.
use super::{common,static_list::blocks_for,Adapter,PlanRow};
use crate::guidelines::doc::{BlockKind,GuidelineDoc,Rights};
use crate::guidelines::fetch::Fetcher;
use crate::guidelines::html::{blocks_from_html,sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::HashSet;
use url::Url;
pub struct BrainTrauma;
const ROOT:&str="https://braintrauma.org/coma/guidelines";
fn catalog(raw:&str,base:&Url)->Result<Vec<(String,String,String)>>{
 let d=Html::parse_document(raw);let mut seen=HashSet::new();let mut out=vec![];
 for item in d.select(&sel("main#page article.blog-item")){let Some(a)=item.select(&sel("h1.blog-title a[href]")).next() else{continue};let title=text_of(&a);let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)) else{continue};if Url::parse(&url)?.origin()!=base.origin()||!seen.insert(url.clone()){continue}let category=item.select(&sel("a.blog-categories")).next().map(|x|text_of(&x)).unwrap_or_default();out.push((url,title,category));}
 if out.is_empty(){bail!("BTF catalog article links missing")};Ok(out)
}
fn page(raw:&str,base:&Url)->Result<(String,String,Option<String>,String,Vec<serde_json::Value>)>{
 let d=Html::parse_document(raw);let title=d.select(&sel("h1.entry-title")).next().map(|x|text_of(&x)).context("BTF entry title missing")?;
 let content=d.select(&sel(".blog-item-content[itemprop='articleBody']")).next().context("BTF entry content missing")?;let html=content.html();let date=d.select(&sel("time.dt-published[datetime]")).next().and_then(|e|e.value().attr("datetime")).map(String::from);
 let status=d.select(&sel("a.blog-item-category")).next().map(|e|text_of(&e)).unwrap_or_default();
 let mut assets=vec![];for p in content.select(&sel("p")){let text=text_of(&p);let role=if text.contains("complete Guidelines") {"full_guideline"}else if text.contains("Executive Summary") {"executive_summary"}else{continue};for a in p.select(&sel("a[href]")){if let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)){if Url::parse(&url)?.path().to_lowercase().ends_with(".pdf"){assets.push(json!({"url":url,"role":role,"source_label":text,"rights":"unknown; not independently acquired"}));}}}}
 Ok((title,html,date,status,assets))
}
fn penetrating_assets(raw:&str,base:&Url)->Result<(String,Vec<serde_json::Value>)>{let d=Html::parse_document(raw);let main=d.select(&sel("main#page")).next().context("BTF penetrating navigation main missing")?;let root=main.select(&sel(".sqs-html-content")).find(|e|{let t=text_of(e);t.contains("Final Supplement")&&t.contains("Penetrating Traumatic Brain Injury")}).context("BTF penetrating final supplement missing")?;let title=root.select(&sel("p")).map(|p|text_of(&p)).find(|t|t.contains("Final Supplement")&&t.contains("Penetrating Traumatic Brain Injury")).context("BTF penetrating supplement title missing")?;let mut assets=vec![];for a in root.select(&sel("ul li a[href]")){let label=text_of(&a);let role=match label.as_str(){"Guidelines"=>"full_guideline","Algorithms"=>"clinical_algorithms","Executive Summary"=>"executive_summary","Dedication"=>"dedication","Forewords"=>"foreword","Sponsorship"=>"sponsorship",_=>continue};if let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)){let u=Url::parse(&url)?;if u.origin()!=base.origin()||!u.path().to_lowercase().ends_with(".pdf"){bail!("BTF supplement link is not a same-source PDF")};assets.push(json!({"url":url,"role":role,"source_label":label,"rights":"unknown"}));}}if !assets.iter().any(|a|a["role"]=="full_guideline")||!assets.iter().any(|a|a["role"]=="clinical_algorithms")||!assets.iter().any(|a|a["role"]=="executive_summary"){bail!("BTF clinical penetrating supplement links missing")};Ok((title,assets))}
fn pdf_rights(blocks:&[crate::guidelines::doc::Block],url:&str)->Rights{let notice=blocks.iter().take(80).map(|b|b.text.as_str()).find(|t|t.contains("Creative Commons Attribution License 4.0 (CC BY)")&&t.contains("provided the original work is properly cited"));if let Some(n)=notice{Rights{status:"open".into(),license:Some("CC-BY-4.0".into()),attribution:Some(n.into()),evidence_urls:vec![url.into()],note:Some("Licence notice applies to this specific publisher PDF; third-party components and other supplement documents require independent rights review.".into()),..Default::default()}}else{Rights{status:"unknown".into(),note:Some("PDF and embedded asset rights not established independently.".into()),..Default::default()}}}
fn recommendation_blocks(html:&str,base:&Url)->(Vec<crate::guidelines::doc::Block>,Vec<String>){
 let (mut blocks,warnings)=blocks_from_html(html,Some(base),None);let level=regex::Regex::new(r"(?i)^LEVEL\s+[IVXAB ,]+(?:AND\s+[IVXAB ]+)?$").unwrap();let mut current=None::<String>;let mut legacy=None::<String>;
 for b in &mut blocks {if matches!(b.kind,BlockKind::Heading{..}){current=None;legacy=None;continue}let t=b.text.trim();if level.is_match(t){current=Some(t.into());legacy=None;continue}if t.to_uppercase().contains("RECOMMENDATIONS FROM THE PRIOR") {legacy=Some(t.into());current=None;continue}if t.eq_ignore_ascii_case("Changes from Prior Edition"){current=None;legacy=None;continue}
  let lower=t.to_lowercase();if current.is_some() && !t.starts_with('*') && !lower.contains("insufficient evidence") && !lower.contains("not supported by evidence") && t.len()>30 && matches!(b.kind,BlockKind::Paragraph|BlockKind::ListItem){b.kind=BlockKind::Recommendation{label:None,strength:current.clone(),certainty:None,population:None,grading_system:None,qualifier:None};}
  else if let Some(q)=&legacy {if t.len()>30 && matches!(b.kind,BlockKind::Paragraph|BlockKind::ListItem){b.kind=BlockKind::Recommendation{label:None,strength:None,certainty:None,population:None,grading_system:None,qualifier:Some(q.clone())};}}
 }(blocks,warnings)
}
#[async_trait::async_trait]
impl Adapter for BrainTrauma {
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{
  if limit==Some(0){return Ok(vec![])}let c=f.get_ok(src.catalog_url.as_deref().unwrap_or(ROOT)).await?;let base=Url::parse(&c.record.final_url)?;let entries=catalog(&c.text(),&base)?;let mut rows=vec![];
  for (url,title,category) in entries {if Url::parse(&url)?.path().trim_end_matches('/')=="/guidelines"{let p=match f.get_ok(&url).await{Ok(p)=>p,Err(e)=>{rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("btf-{}-unresolved",common::short_hash(&url)),url,title:Some(title),rendition:None,version:None,extra:json!({"discovery_error":format!("BTF penetrating navigation unavailable: {e:#}")})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};let actual=Url::parse(&p.record.final_url)?;if actual.origin()!=base.origin(){bail!("BTF penetrating navigation redirected outside source")};let (supplement,assets)=match penetrating_assets(&p.text(),&actual){Ok(x)=>x,Err(e)=>{rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("btf-{}-unresolved",common::short_hash(&url)),url,title:Some(title),rendition:None,version:None,extra:json!({"discovery_error":format!("BTF penetrating navigation template: {e:#}")})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};for a in &assets{let role=a["role"].as_str().unwrap_or_default();if !matches!(role,"full_guideline"|"clinical_algorithms"|"executive_summary"){continue}let target=a["url"].as_str().unwrap().to_string();let mut r=PlanRow{source_id:src.id.clone(),doc_key:format!("btf-{}-unresolved",common::short_hash(&target)),url:target.clone(),title:Some(format!("{} ({})",supplement,role)),rendition:Some("pdf".into()),version:Some("Second Edition".into()),extra:json!({"pdf_role":role,"parent_url":url,"source_label":a["source_label"],"supplement_assets":assets,"navigation_fetch":p.record})};match f.get_ok(&target).await{Ok(q) if q.is_pdf()=>{r.doc_key=format!("btf-{}-{}",common::short_hash(&target),&q.record.sha256[..12]);r.extra["pdf_sha256"]=json!(q.record.sha256)},Ok(_)=>r.extra["discovery_error"]=json!("BTF source supplement did not return a PDF"),Err(e)=>r.extra["discovery_error"]=json!(format!("{e:#}"))};rows.push(r);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}continue}let mut pending_assets=vec![];let mut row=PlanRow{source_id:src.id.clone(),doc_key:format!("btf-{}-unresolved",common::short_hash(&url)),url:url.clone(),title:Some(title),rendition:Some("html".into()),version:None,extra:json!({"catalog_fetch":c.record,"catalog_category":category})};
   match f.get_ok(&url).await{Ok(p)=>{let final_url=Url::parse(&p.record.final_url)?;if final_url.origin()!=base.origin(){row.extra["discovery_error"]=json!("BTF page redirected outside source origin");}else{match page(&p.text(),&final_url){Ok((title,html,date,status,assets))=>{let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&html,&date,&status,&assets))?.as_bytes());row.doc_key=format!("btf-{}-{}",common::short_hash(&url),&hash[..12]);row.title=Some(title);row.extra["content_sha256"]=json!(hash);pending_assets=assets;},Err(e)=>row.extra["discovery_error"]=json!(format!("{e:#}"))}}},Err(e)=>row.extra["discovery_error"]=json!(format!("{e:#}"))};let parent_title=row.title.clone();rows.push(row);if limit.is_some_and(|n|rows.len()>=n){break}
   for asset in pending_assets {let Some(pdf)=asset["url"].as_str().map(String::from) else{continue};let role=asset["role"].as_str().unwrap_or("asset").to_string();let mut r=PlanRow{source_id:src.id.clone(),doc_key:format!("btf-{}-unresolved",common::short_hash(&pdf)),url:pdf.clone(),title:parent_title.clone().map(|t|format!("{t} ({role})")),rendition:Some("pdf".into()),version:None,extra:json!({"pdf_role":role,"parent_url":url,"source_label":asset["source_label"]})};
    match f.get_ok(&pdf).await {Ok(q) if q.is_pdf()=>{r.doc_key=format!("btf-{}-{}",common::short_hash(&pdf),&q.record.sha256[..12]);r.extra["pdf_sha256"]=json!(q.record.sha256);},Ok(_)=>r.extra["discovery_error"]=json!("BTF linked asset did not return PDF"),Err(e)=>r.extra["discovery_error"]=json!(format!("{e:#}"))};rows.push(r);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}
   }
  }
  Ok(rows)
 }
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{
  if let Some(e)=row.extra["discovery_error"].as_str(){bail!("BTF discovery: {e}")};
  if row.rendition.as_deref()==Some("pdf") {let p=f.get_ok(&row.url).await?;if !p.is_pdf() || row.extra["pdf_sha256"].as_str()!=Some(p.record.sha256.as_str()){bail!("BTF PDF changed or is unavailable; re-plan")};let (blocks,mut warnings,_)=blocks_for(&p,None,30).await?;if blocks.is_empty(){bail!("BTF PDF yielded no text")};warnings.push("PDF figures, visual algorithms, tables, nested qualifications and page fidelity require original-source review; no grade inferred.".into());let rights=pdf_rights(&blocks,&row.url);return Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),title:row.title.clone().unwrap_or_default(),url:row.url.clone(),item_type:row.extra["pdf_role"].as_str().map(String::from),version:row.version.clone(),status:"unknown".into(),rights,blocks,fetches:vec![p.record],warnings,search_metadata:json!({"parent_index":row.extra["parent_url"],"source_label":row.extra["source_label"],"supplement_assets":row.extra["supplement_assets"]}),..Default::default()});}
  let p=f.get_ok(&row.url).await?;let base=Url::parse(&p.record.final_url)?;if base.origin()!=Url::parse(ROOT)?.origin(){bail!("BTF redirected outside source")};let (title,html,date,status,assets)=page(&p.text(),&base)?;let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&html,&date,&status,&assets))?.as_bytes());if row.extra["content_sha256"].as_str()!=Some(hash.as_str()){bail!("BTF article changed; re-plan")}
  let (blocks,mut warnings)=recommendation_blocks(&html,&base);if blocks.is_empty(){bail!("BTF content empty")};warnings.push("This publisher HTML is a recommendation index or summary, not the complete PDF, methods or evidence review. PDF and other attachment rights and access have not been established.".into());warnings.push("Accordion nesting, lists, conditional wording and absent/insufficient evidence must be checked against the original; only explicitly labelled levels are represented and old-edition qualifiers remain local.".into());
  let item_type=if title.to_lowercase().contains("systematic review"){"systematic_review"}else if title.to_lowercase().contains("algorithm"){"algorithm"}else{"recommendation_index"};let dates=date.map(|d|vec![common::date("Website entry date",&d,&row.url)]).unwrap_or_default();let rights=Rights{status:"unknown".into(),note:Some("HTML and linked asset permissions are not established.".into()),..Default::default()};
  Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:Some(format!("btf-{}",common::short_hash(&row.url))),title,url:row.url.clone(),item_type:Some(item_type.into()),status:if status.eq_ignore_ascii_case("Current"){"current".into()}else if status.eq_ignore_ascii_case("Archive"){"archived".into()}else{"unknown".into()},rights,date_observations:dates,blocks,attachments:assets,fetches:vec![p.record],warnings,search_metadata:json!({"source_category":status}),..Default::default()})
 }
}
#[cfg(all(test, feature = "guideline-fixtures"))] mod tests {
 use super::*;
 const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/catalog.html"));
 const SEVERE:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/severe.html"));
 const SURGICAL:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/surgical.html"));
 #[test] fn actual_catalog_and_accordion_roles_and_levels(){
  let base=Url::parse(ROOT).unwrap();let entries=catalog(CAT,&base).unwrap();assert_eq!(entries.len(),13);assert!(entries.iter().any(|(u,_,s)|u.ends_with("/severe-tbi-3rd-edition")&&s=="Archive"));
  let u=Url::parse("https://braintrauma.org/coma/guidelines/severe-tbi").unwrap();let (title,html,date,status,assets)=page(SEVERE,&u).unwrap();assert!(title.contains("4th Edition"));assert_eq!(date.as_deref(),Some("2016-09-30"));assert_eq!(status,"Current");assert!(assets.iter().any(|a|a["role"]=="full_guideline"));assert!(assets.iter().any(|a|a["role"]=="executive_summary"));
  let (b,_)=recommendation_blocks(&html,&u);assert!(b.iter().any(|b|matches!(&b.kind,BlockKind::Recommendation{strength:Some(s),..} if s=="LEVEL II A") && b.text.contains("Bifrontal DC")));assert!(b.iter().any(|b|matches!(b.kind,BlockKind::Paragraph) && b.text.contains("insufficient evidence to support a Level I")));assert!(b.iter().any(|b|matches!(&b.kind,BlockKind::Recommendation{qualifier:Some(q),..} if q.contains("PRIOR")) && b.text.contains("Mannitol")));
  let (_,html,date,_,assets)=page(SURGICAL,&Url::parse("https://braintrauma.org/coma/guidelines/surgical").unwrap()).unwrap();assert_eq!(date.as_deref(),Some("2006-03-31"));assert!(assets.iter().any(|a|a["url"].as_str().is_some_and(|s|s.ends_with("Surgical_Management_of_TBI.pdf"))));assert!(html.contains("Indications for Surgery") && html.contains("Timing") && html.contains("Methods"));
 }
 #[tokio::test] async fn actual_summary_offline_is_not_full_pdf(){let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");let url="https://braintrauma.org/coma/guidelines/severe-tbi";f.seed_cache_for_tests(url,SEVERE.as_bytes(),"text/html");let src:SourceEntry=serde_json::from_value(json!({"id":"brain_trauma_foundation","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=BrainTrauma.discover(&src,&f,None).await.unwrap();let row=rows.iter().find(|r|r.url==url).unwrap();let d=BrainTrauma.extract(&src,&f,row).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("recommendation_index"));assert!(d.date_observations.iter().any(|d|d.label=="Website entry date"));assert!(d.warnings.iter().any(|w|w.contains("not the complete PDF")));assert!(d.attachments.iter().any(|a|a["role"]=="full_guideline"));}
 #[test]fn source_penetrating_navigation_has_six_distinct_roles(){let nav=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/penetrating-navigation.html"));let(title,a)=penetrating_assets(nav,&Url::parse("https://braintrauma.org/guidelines").unwrap()).unwrap();assert!(title.contains("Second Edition"));assert_eq!(a.len(),6);for role in ["full_guideline","clinical_algorithms","executive_summary","dedication","foreword","sponsorship"]{assert!(a.iter().any(|x|x["role"]==role));}}
 #[tokio::test]async fn source_navigation_expands_clinical_pdf_rows(){let nav=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/penetrating-navigation.html"));let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");f.seed_cache_for_tests("https://braintrauma.org/guidelines",nav.as_bytes(),"text/html");let src:SourceEntry=serde_json::from_value(json!({"id":"brain_trauma_foundation","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=BrainTrauma.discover(&src,&f,Some(3)).await.unwrap();assert_eq!(rows.len(),3);assert!(rows.iter().all(|r|r.rendition.as_deref()==Some("pdf")&&r.extra["discovery_error"].is_string()));for role in ["full_guideline","clinical_algorithms","executive_summary"]{assert!(rows.iter().any(|r|r.extra["pdf_role"]==role));}assert!(!rows.iter().any(|r|r.url=="https://braintrauma.org/guidelines"));}

 #[test]fn genuine_penetrating_component_roles_have_independent_rights_and_clinical_evidence(){let guideline=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/penetrating-guideline-blocks.json"));let algorithms=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/penetrating-algorithms-blocks.json"));let executive=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/brain_trauma_foundation/penetrating-executive-blocks.json"));let g:Vec<crate::guidelines::doc::Block>=serde_json::from_str(guideline).unwrap();let a:Vec<crate::guidelines::doc::Block>=serde_json::from_str(algorithms).unwrap();let e:Vec<crate::guidelines::doc::Block>=serde_json::from_str(executive).unwrap();let gr=pdf_rights(&g,"https://braintrauma.org/s/4_pTBI_2nd_edition_guidelines.pdf");let ar=pdf_rights(&a,"https://braintrauma.org/s/5_pTBI_2nd_edition_treatment_algorithms.pdf");assert_eq!(gr.license.as_deref(),Some("CC-BY-4.0"));assert_eq!(ar.license.as_deref(),Some("CC-BY-4.0"));assert_eq!(pdf_rights(&e,"https://braintrauma.org/s/pTBI_2nd_edition_executive_summary.pdf").status,"unknown");assert!(g.iter().any(|b|b.text.contains("Level C – Expert Consensus")&&b.text.contains("absence of direct scientific evidence")));assert!(a.iter().any(|b|b.text.contains("Treatment Algorithms")));assert!(e.iter().any(|b|b.text.contains("Executive summary")));assert_ne!(gr.evidence_urls,ar.evidence_urls);}

}
